		'1import\u001f0 { DataTable, \u001f1type\u001f0 DataTableEmptyState } \u001f1from\u001f0 \u001f4"@workspace/ui-native/components/data-table"\u001f0;\n1import\u001f0 { SegmentedControl, \u001f1type\u001f0 SegmentedOption } \u001f1from\u001f0 \u001f4"@workspace/ui-native/components/segmented-control"\u001f0;\n1import\u001f0 \u001f3*\u001f0 \u001f1as\u001f0 React \u001f1from\u001f0 \u001f4"react"\u001f0;\n1import\u001f0 { View } \u001f1from\u001f0 \u001f4"react-native"\u001f0;\n\n1import\u001f0 { DOCUMENT_SECTIONS, SECTION_COLUMNS, SECTION_PAGINATION } \u001f1from\u001f0 \u001f4"./data-table-sample"\u001f0;\n\n1const\u001f0 \u001f3PAGE_SIZE\u001f0 \u001f1=\u001f0 \u001f35\u001f0;\n1const\u001f0 \u001f3SKELETON_ROWS\u001f0 \u001f1=\u001f0 \u001f35\u001f0;\n\n1type\u001f0 \u001f2TableState\u001f0 \u001f1=\u001f0 \u001f4"loaded"\u001f0 \u001f1|\u001f0 \u001f4"loading"\u001f0 \u001f1|\u001f0 \u001f4"refetching"\u001f0 \u001f1|\u001f0 \u001f4"empty"\u001f0 \u001f1|\u001f0 \u001f4"error"\u001f0;\n\n1const\u001f0 \u001f3STATES\u001f1:\u001f0 \u001f1readonly\u001f0 \u001f2SegmentedOption\u001f0<\u001f2TableState\u001f0>[] \u001f1=\u001f0 [\n0\t{ value: \u001f4"loading"\u001f0, label: \u001f4"Load"\u001f0 },\n0\t{ value: \u001f4"loaded"\u001f0, label: \u001f4"Rows"\u001f0 },\n0\t{ value: \u001f4"refetching"\u001f0, label: \u001f4"Refetch"\u001f0 },\n0\t{ value: \u001f4"empty"\u001f0, label: \u001f4"Empty"\u001f0 },\n0\t{ value: \u001f4"error"\u001f0, label: \u001f4"Error"\u001f0 },\n0];\n\n1const\u001f0 \u001f3EMPTY\u001f1:\u001f0 \u001f2DataTableEmptyState\u001f0 \u001f1=\u001f0 { title: \u001f4"No sections yet"\u001f0, description: \u001f4"Sections appear here once the proposal has some."\u001f0 };\n\n1export\u001f0 \u001f1function\u001f0 \u001f2DataTable11Example\u001f0()\u001f1:\u001f0 \u001f2React\u001f0.\u001f2JSX\u001f0.\u001f2Element\u001f0 {\n0\t\u001f1const\u001f0 [\u001f3state\u001f0, \u001f3setState\u001f0] \u001f1=\u001f0 React.\u001f2useState\u001f0<\u001f2TableState\u001f0>(\u001f4"loading"\u001f0);\n0\t\u001f1const\u001f0 \u001f3retry\u001f0 \u001f1=\u001f0 React.\u001f2useCallback\u001f0(()\u001f1:\u001f0 \u001f3void\u001f0 \u001f1=>\u001f0 {\n0\t\t\u001f2setState\u001f0(\u001f4"loaded"\u001f0);\n0\t}, []);\n0\t\u001f1return\u001f0 (\n0\t\t<\u001f3View\u001f0 \u001f2className\u001f1=\u001f4"w-full gap-4"\u001f0>\n0\t\t\t<\u001f3SegmentedControl\u001f0 \u001f2label\u001f1=\u001f4"Table state"\u001f0 \u001f2options\u001f1=\u001f0{\u001f3STATES\u001f0} \u001f2value\u001f1=\u001f0{state} \u001f2onChange\u001f1=\u001f0{setState} />\n0\t\t\t<\u001f3DataTable\n0\t\t\t\t\u001f2data\u001f1=\u001f0{state \u001f1===\u001f0 \u001f4"empty"\u001f0 \u001f1?\u001f0 [] \u001f1:\u001f0 \u001f3DOCUMENT_SECTIONS\u001f0}\n0\t\t\t\t\u001f2columns\u001f1=\u001f0{\u001f3SECTION_COLUMNS\u001f0}\n0\t\t\t\t\u001f2isLoading\u001f1=\u001f0{state \u001f1===\u001f0 \u001f4"loading"\u001f0}\n0\t\t\t\t\u001f2isRefetching\u001f1=\u001f0{state \u001f1===\u001f0 \u001f4"refetching"\u001f0}\n0\t\t\t\t\u001f2skeletonRows\u001f1=\u001f0{\u001f3SKELETON_ROWS\u001f0}\n0\t\t\t\t\u001f2error\u001f1=\u001f0{state \u001f1===\u001f0 \u001f4"error"\u001f0 \u001f1?\u001f0 \u001f4"The sections could not be loaded. Try again in a moment."\u001f0 \u001f1:\u001f0 \u001f3null\u001f0}\n0\t\t\t\t\u001f2onRetry\u001f1=\u001f0{retry}\n0\t\t\t\t\u001f2emptyState\u001f1=\u001f0{\u001f3EMPTY\u001f0}\n0\t\t\t\t\u001f2pagination\u001f1=\u001f0{\u001f3SECTION_PAGINATION\u001f0}\n0\t\t\t\t\u001f2pageSize\u001f1=\u001f0{\u001f3PAGE_SIZE\u001f0}\n0\t\t\t\t\u001f2title\u001f1=\u001f4"Loading, empty and error"\n0\t\t\t\t\u001f2description\u001f1=\u001f4"Every state a fetched table goes through, from skeleton rows to an error."\n0\t\t\t/>\n0\t\t</\u001f3View\u001f0>\n0\t);\n0}',
